compile.workshop:
variables {
    global:
        0: arr
        1: result
}

rule ("enabled zero indexing") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, First Of(Global.arr));
        Set Global Variable(result, First Of(Global.arr));
        Set Global Variable(result, Value In Array(Global.arr, 1));
    }
}

//Optimizations disabled
rule ("disabled zero indexing") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, Value In Array(Global.arr, 0));
        Set Global Variable(result, Value In Array(Global.arr, 0.0));
        Set Global Variable(result, Value In Array(Global.arr, 1));
        Set Global Variable(result, Value In Array(Empty Array, 0));
        Set Global Variable(result, Value In Array(Empty Array, 0.0));
        Set Global Variable(result, Value In Array(Empty Array, 1));
    }
}

//Optimizations enabled
rule ("reenabled zero indexing") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, First Of(Global.arr));
    }
}

//Strict optimizations enabled
rule ("strict empty array indexing") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, First Of(Empty Array));
        Set Global Variable(result, First Of(Empty Array));
        Set Global Variable(result, Value In Array(Empty Array, 1));
        Set Global Variable(result, Value In Array(Empty Array, 0.1));
        Set Global Variable(result, Value In Array(Empty Array, 0.49));
    }
}

